window.HOEREN_TESTS[32] = {"id":"camping-und-wandern","name":"Camping und Wandern","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Wanderer im Alpenpark, eine wichtige Information: Der Wanderweg zum Großen See ist heute gesperrt, weil es am Berghang glatt ist. Sie können stattdessen den Weg zum Kleinen See nehmen, der ist sicher. Die Bergbahn-Strecke ist offen, die Bahn fährt normal. Bitte bleiben Sie auf den offenen Wegen und beachten Sie die Schilder.","gender":"m","q":"Welcher Weg ist heute gesperrt?","opts":["Zum Kleinen See.","Zum Großen See.","Die Bergbahn-Strecke."],"correct":1},{"transcript":"Hallo Herr Schmidt, hier ist der Campingplatz Bergblick. Ihre Reservierung: Sie haben einen Zelt-Platz für eine Woche bestellt, die Dauer bleibt gleich. Der Preis ändert sich auch nicht. Aber der genaue Platz ist jetzt Platz 27, in der Nähe der Duschen, etwas weiter vom See. Ist das okay? Bitte sagen Sie uns Bescheid.","gender":"f","q":"Was hat sich geändert?","opts":["Die Reservierungsdauer.","Der Preis.","Der genaue Platz."],"correct":2},{"transcript":"Achtung an alle Bergsteiger: Wegen plötzlichem Schnee sind die roten Pisten und die schwarzen Pisten ab heute Mittag gesperrt. Blaue und Anfänger-Pisten sind sicher und offen, auch alle leichten Wege im Tal. Wenn das Wetter besser wird, öffnen wir morgen wieder mehr. Sicherheit zuerst!","gender":"m","q":"Was ist sicher und offen?","opts":["Blaue und Anfänger-Pisten.","Schwarze Pisten.","Rote Pisten."],"correct":0},{"transcript":"Hi Schatz, hier ist Mama. Hör mal, die Wanderung am Wochenende: Meine Schwester kommt überraschend zu Besuch, und ich bleibe zu Hause wegen Besuch. Ich komme also nicht mit zur Wanderung, und ich mache auch keine andere Wanderung. Schade, du gehst trotzdem mit deinem Vater? Bringt mir Fotos mit, und vergesst nicht warme Sachen.","gender":"f","q":"Was macht Mama am Wochenende?","opts":["Sie kommt mit zur Wanderung.","Sie macht eine andere Wanderung.","Sie bleibt zu Hause wegen Besuch."],"correct":2},{"transcript":"Liebe Gäste vom Berghotel Edelweiss, ein Wetterbericht für morgen: Es wird sonnig, 16 Grad, mit nur leichten Wolken am Nachmittag. Nicht regnerisch und auch kein Schnee, also perfekt für eine Bergwanderung. Wir empfehlen die Tour zum Mittelsee, drei Stunden hin und zurück. Karten und Wasser bekommen Sie an der Rezeption.","gender":"f","q":"Wie wird das Wetter morgen?","opts":["Sonnig, 16 Grad.","Regnerisch.","Schnee."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer bringt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Holger","gender":"m","text":"Hallo! Am Wochenende fahren wir endlich zusammen raus in die Natur."},{"speaker":"Andrea","gender":"f","text":"Jeder soll etwas mitnehmen. Sonst fehlt am Abend die Hälfte."},{"speaker":"Holger","gender":"m","text":"Die Zelte nehme ich mit. Sie liegen bei mir schon im Keller."},{"speaker":"Andrea","gender":"f","text":"Zwei Stück reichen locker, Holger."},{"speaker":"Holger","gender":"m","text":"Sollen wir warme Decken extra mitnehmen?"},{"speaker":"Andrea","gender":"f","text":"Nein. Warme Decken brauchen wir nicht."},{"speaker":"Holger","gender":"m","text":"Wer kocht abends draußen am Platz, Andrea?"},{"speaker":"Andrea","gender":"f","text":"Um das Essen kümmere ich mich. Suppe und Brot stehen auf meiner Liste."},{"speaker":"Holger","gender":"m","text":"Lukas will unbedingt selbst das Feuer machen."},{"speaker":"Andrea","gender":"f","text":"Lukas bringt den Camping-Grill und Holz. Beides steht bei ihm im Schuppen."},{"speaker":"Holger","gender":"m","text":"Lisa sitzt abends nicht gern nur herum."},{"speaker":"Andrea","gender":"f","text":"Lisa packt Spiele und Bücher ein. Damit wird der Abend danach ruhig."},{"speaker":"Holger","gender":"m","text":"Packt noch jemand das Geschirr ein?"},{"speaker":"Andrea","gender":"f","text":"Nein. Geschirr packt auch keiner ein."},{"speaker":"Holger","gender":"m","text":"Anna friert nachts sehr schnell."},{"speaker":"Andrea","gender":"f","text":"Anna nimmt Schlafsäcke und Isomatten mit. Die dicken Sachen liegen im Schrank."},{"speaker":"Holger","gender":"m","text":"Ich lege die fertige Liste oben auf den Rucksack."},{"speaker":"Andrea","gender":"f","text":"Morgen früh laden wir alles ganz ruhig in den Kofferraum."}],"options":[{"letter":"a","text":"bringt warme Decken"},{"letter":"b","text":"kümmert sich um das Essen"},{"letter":"c","text":"bringt Camping-Grill und Holz"},{"letter":"d","text":"bringt Spiele und Bücher"},{"letter":"e","text":"bringt das Geschirr"},{"letter":"f","text":"bringt die Zelte"},{"letter":"g","text":"macht die Wanderpläne"},{"letter":"h","text":"bringt Schlafsäcke und Isomatten"},{"letter":"i","text":"fährt das Auto"}],"items":[{"person":"Holger","correct":"f"},{"person":"Andrea","correct":"b"},{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"d"},{"person":"Anna","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Camping-Mitarbeiter","gender":"m","text":"Guten Tag, wie lange möchten Sie bleiben?"},{"speaker":"Kunde","gender":"m","text":"Eine Woche, mit Zelt, was kostet das, 105 Euro, 140 oder 175?"},{"speaker":"Camping-Mitarbeiter","gender":"m","text":"Zelt 15 Euro pro Nacht, Wohnwagen 25 Euro. Mit Strom 5 Euro extra."},{"speaker":"Kunde","gender":"m","text":"Zelt mit Strom, bitte, also nicht nur 105 ohne Strom, und nicht 175 wie beim Wohnwagen."},{"speaker":"Camping-Mitarbeiter","gender":"m","text":"Genau, das macht 140 Euro für die Woche. Anreise ab 14 Uhr."}],"q":"Wie viel zahlt der Kunde?","opts":["105 Euro.","175 Euro.","140 Euro."],"correct":2},{"lines":[{"speaker":"Wanderfreundin","gender":"f","text":"Welchen Weg sollen wir nehmen? Die kurze Tour, 5 Kilometer, oder die lange, 12 Kilometer?"},{"speaker":"Wanderfreund","gender":"m","text":"Die kurze Tour, 5 Kilometer, oder die lange, 12 Kilometer, wenn du fit bist."},{"speaker":"Wanderfreundin","gender":"f","text":"12 ist zu viel für mich heute. Eine andere Tour brauchen wir nicht, die kurze reicht."},{"speaker":"Wanderfreund","gender":"m","text":"Dann die kurze, wir können nächste Woche die lange machen, wenn das Wetter gut bleibt."},{"speaker":"Wanderfreundin","gender":"f","text":"Super, dann starten wir in zehn Minuten am Parkplatz."}],"q":"Welche Tour wählen sie?","opts":["5 Kilometer.","12 Kilometer.","Eine andere."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Was brauchen wir noch für das Wandern? Wasser habe ich, aber sonst?"},{"speaker":"Sohn","gender":"m","text":"Wasser und Brotzeit, die Karte auch, oder?"},{"speaker":"Vater","gender":"m","text":"Die Karte habe ich, was ist mit Sonnencreme? Die vergesse ich fast immer."},{"speaker":"Sohn","gender":"m","text":"Stimmt! Mama hat eine in ihrem Rucksack. Ohne Sonnencreme gehen wir nicht."},{"speaker":"Vater","gender":"m","text":"Gut, dann holen wir die Creme noch schnell. Wasser und Karte sind schon im Rucksack."}],"q":"Was vergisst der Vater fast?","opts":["Wasser.","Sonnencreme.","Karte."],"correct":1},{"lines":[{"speaker":"Wanderer","gender":"m","text":"Entschuldigung, wie weit ist es noch zur Hütte? Schaffen wir das, oder sollen wir umkehren?"},{"speaker":"Wanderin","gender":"f","text":"Eine Stunde Gehzeit, aber ein steiler Aufstieg. Eine andere Route ist von hier nicht besser."},{"speaker":"Wanderer","gender":"m","text":"Schaffe ich das mit meinen Kindern? Sie sind noch klein."},{"speaker":"Wanderin","gender":"f","text":"Wie alt sind sie denn?"},{"speaker":"Wanderer","gender":"m","text":"6 und 8 Jahre, sollen wir umkehren?"},{"speaker":"Wanderin","gender":"f","text":"Sie schaffen das, mit Pause. Umkehren müssen Sie nicht, und eine andere Route brauchen Sie auch nicht."}],"q":"Was empfiehlt die Wanderin?","opts":["Eine andere Route nehmen.","Sie sollten umkehren.","Sie schaffen es, mit Pause."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, ich brauche neue Wanderschuhe. Haben Sie auch Trainingsschuhe?"},{"speaker":"Verkäufer","gender":"m","text":"Trainingsschuhe haben wir, ja, aber suchen Sie Schuhe für leichte Spaziergänge oder für schwere Berge?"},{"speaker":"Frau","gender":"f","text":"Eher für schwere Berge, ich mag anstrengende Touren. Trainingsschuhe sind mir zu weich."},{"speaker":"Verkäufer","gender":"m","text":"Dann dieses Modell hier, fest und wasserdicht, 150 Euro. Für leichte Spaziergänge wäre es zu viel."},{"speaker":"Frau","gender":"f","text":"Gut, ich nehme die für schwere Berge. Kann ich sie gleich anziehen?"}],"q":"Welche Wanderschuhe?","opts":["Für schwere Berge.","Für leichte Spaziergänge.","Trainingsschuhe."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Vogel, einem Bergführer. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Vogel, Sie sind seit 22 Jahren Bergführer in den Alpen. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Vogel","gender":"m","text":"Ich bin in den Bergen aufgewachsen — mein Vater war Schäfer. Schon mit 12 Jahren habe ich erste schwere Touren gemacht. Eigentlich wollte ich Geologe werden, aber Bergführer war für mich näher dran."},{"speaker":"Reporter","gender":"m","text":"Welche Gruppen führen Sie?"},{"speaker":"Vogel","gender":"m","text":"Sehr unterschiedlich, anfänger zu mittleren Touren — Spaziergänge zu schönen Aussichtspunkten. Erfahrene Wanderer auf schwere Bergstrecken. Manchmal auch Kinder-Familien — die brauchen besondere Geduld."},{"speaker":"Reporter","gender":"m","text":"Was ist das gefährlichste?"},{"speaker":"Vogel","gender":"m","text":"Wetter-Wechsel. Im Sommer kann ein plötzliches Gewitter sehr gefährlich sein. Im Winter Schneestürme. Wir prüfen das Wetter vor jeder Tour sehr genau. Lieber absagen als ein Risiko eingehen."},{"speaker":"Reporter","gender":"m","text":"Was sind häufige Fehler von Anfängern?"},{"speaker":"Vogel","gender":"m","text":"Sie nehmen zu wenig Wasser mit. Sie tragen schlechte Schuhe — Turnschuhe sind keine Wanderschuhe! Und sie unterschätzen die Höhe — schon ab 2000 Meter braucht der Körper Anpassung."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie selbst in der Freizeit?"},{"speaker":"Vogel","gender":"m","text":"Lese viel — ich habe ja viel Zeit auf dem Berg, wenn die Gruppe pausiert. Und ich male — Landschaften, was sonst? Ein anderes Hobby weit weg von den Bergen habe ich nicht."}],"items":[{"q":"Wetter-Wechsel sind besonders gefährlich.","correct":"ja"},{"q":"Sein Vater war auch Bergführer.","correct":"nein"},{"q":"Turnschuhe sind okay für leichte Wanderungen.","correct":"nein"},{"q":"Ab 2000 Meter Höhe muss man sich anpassen.","correct":"ja"},{"q":"In der Freizeit hat er Hobbys weit weg von den Bergen.","correct":"nein"}]}]};
